 ["Drowning panic peak"] = "溺水恐慌峰值",
 ["Druid"] = "德魯伊",
 ["Dual asymmetrical ERM motors, balanced 75ms spin-up"] = "雙非對稱 ERM 馬達，平衡 75 毫秒起轉",
 ["Dual-motor rumble & vibration schemas"] = "雙馬達震動配置",
 ["DualSense (PS5)"] = "DualSense (PS5)",
 ["DualShock 4 (PS4)"] = "DualShock 4 (PS4)",
 ["Duel request"] = "決鬥請求",
 ["Dungeon queue popped"] = "地城排隊就緒",
 ["Dungeon: Caster"] = "地城：法系",
 ["Dungeon: Caster DPS"] = "地城：法系傷害輸出",
 ["Dungeon: Healer"] = "地城：治療者",
 ["Dungeon: Hunter"] = "地城：獵人",
 ["Dungeon: Melee"] = "地城：近戰",
 ["Dungeon: Melee DPS"] = "地城：近戰傷害輸出",
 ["Dungeon: Tank"] = "地城：坦克",
 ["Dungeons & Raids"] = "地城與團隊副本",
 ["Duration"] = "持續時間",
 ["Duration of the software overdrive kick. 0.030s on heavy ERM counterweights, 0.0 on LRAs."] = "軟體超驅動衝擊的持續時間。重型 ERM 偏心轉子馬達建議為 0.030 秒，LRA 線性馬達則為 0.0 秒。",
 ["Effort only, routed by default to the heavy motor alongside \"In water\", so the two merge into natural fluid resistance with clean glide coast-down between strokes. Turn on \"Own motor\" only if you want the stroke isolated on the high-frequency motor. Scales on your speed relative to your own swim speed, so it is silent while floating."] = "僅限划水阻力，預設與「在水中」一同路由至重震馬達，使兩者融合成自然的流體阻力，並在划水動作之間帶來流暢的滑行減速感。僅在你希望將划水動作獨立於高頻馬達時才開啟「獨立馬達」。依據相對於自身游泳速度的移動速度進行縮放，因此在漂浮時保持靜音。",
 ["Effort peak"] = "發力峰值",
