 ["Rename"] = "重新命名",
 ["Rename \"%s\" to:"] = "將「%s」重新命名為：",
 ["Rename the profile in use. Every rule pointing at it follows the rename. Built-in profiles can't be renamed."] = "重新命名使用中的設定檔。指向該設定檔的所有規則都將同步更新名稱。內建設定檔無法重新命名。",
 ["Rename this profile"] = "重新命名此設定檔",
