 ["Spec %s"] = "專精 %s",
 ["Special casting"] = "特殊施法",
 ["Speeds up or slows down "] = "加快或減慢 ",
 ["Speeds up or slows down %s as a whole — both its pulses and the gaps between them, so a multi-hit mode keeps its rhythm instead of the hits stretching into their own gaps. 1.0 is the authored default."] = "加速或減慢 %s 作為一個整體——包括其脈衝以及脈衝之間的間隔，進而使多重打擊模式保持其固有節奏，而不是讓打擊延伸進入其自身的間隔中。1.0 為預設設計值。",
 ["Spell activation proc"] = "法術觸發效果",
 ["Spell flow, instant casts, and interrupts"] = "施法節奏、瞬發法術與斷法",
 ["Spellcasting Channel Hum"] = "施法引導嗡鳴",
 ["Spirit healer"] = "靈魂醫者",
 ["Split left and right"] = "左右聲道分離",
 ["Square / X: open settings"] = "Square / X: 開啟設定",
 ["Stable opened"] = "獸欄已開啟",
 ["Staccato"] = "斷奏",
